package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
public class AdcBlock extends BaseEntityBlock{
 public static final DirectionProperty FACING=BlockStateProperties.HORIZONTAL_FACING;public static final IntegerProperty PART=IntegerProperty.create("part",0,244);public static final ThreadLocal<Boolean>MUTATING=ThreadLocal.withInitial(()->false);
 public AdcBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(FACING,Direction.NORTH).setValue(PART,0));}@Override protected com.mojang.serialization.MapCodec<? extends BaseEntityBlock>codec(){return simpleCodec(AdcBlock::new);}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(FACING,PART);}
 public static BlockPos root(BlockPos p,BlockState s){return AdcGeometry.MODEL.root(p,s.getValue(FACING),s.getValue(PART));}public static AdcBlockEntity main(Level l,BlockPos p,BlockState s){var r=root(p,s);return l.hasChunkAt(r)&&l.getBlockEntity(r)instanceof AdcBlockEntity b?b:null;}
 @Override public BlockState getStateForPlacement(net.minecraft.world.item.context.BlockPlaceContext c){return defaultBlockState().setValue(FACING,DefenseItem.face(c.getPlayer(),c.getItemInHand()));}
 @Override public void setPlacedBy(Level l,BlockPos p,BlockState s,LivingEntity placer,net.minecraft.world.item.ItemStack item){if(l.getBlockEntity(p)instanceof AdcBlockEntity b){var n=DefenseItem.data(item);if(n.contains("Installation"))b.restore(n.getCompound("Installation"));b.id=java.util.UUID.randomUUID();if(b.owner==null&&placer!=null){b.owner=placer.getUUID();b.ownerName=placer.getScoreboardName();}if(l instanceof net.minecraft.server.level.ServerLevel sl)DefenseData.get(sl).register(new DefenseData.Site(b.id,3,p,s.getValue(FACING),b.owner,b.ownerName));b.changed();}}
 public static BlockHitResult clip(AdcBlockEntity source,Vec3 a,Vec3 b){return source.getLevel().clip(new ClipContext(a,b,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,CollisionContext.empty()){@Override public VoxelShape getBlockShape(BlockState s,BlockGetter l,BlockPos p){return s.getBlock()instanceof AdcBlock&&root(p,s).equals(source.getBlockPos())?Shapes.empty():super.getBlockShape(s,l,p);}});}
 public InteractionResult interact(BlockState s,Level l,BlockPos p,Player player,InteractionHand hand){if(player.getItemInHand(hand).getItem()instanceof AdcItem)return InteractionResult.PASS;var b=main(l,p,s);if(b==null)return InteractionResult.FAIL;if(player.getItemInHand(hand).getItem()instanceof DefenseLinkTool){if(player instanceof net.minecraft.server.level.ServerPlayer sp&&sp.distanceToSqr(Vec3.atCenterOf(p))<36&&b.permitted(sp)){if(player.isShiftKeyDown()){DefenseData.get(sp.serverLevel()).unlink(b.id);b.radarId=null;b.radarState="NO_RADAR";b.changed();return DefenseLinkTool.reply(sp,"UNLINKED");}return DefenseLinkTool.link(sp,player.getItemInHand(hand),b.id);}return InteractionResult.sidedSuccess(l.isClientSide);}if(l.isClientSide){AdcClient.open(b);return InteractionResult.SUCCESS;}if(player instanceof net.minecraft.server.level.ServerPlayer sp&&b.canOperate(sp)){if(player.isShiftKeyDown()&&player.getItemInHand(hand).is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR)){if(AdcEvents.mayRemove(sp,b))b.remove(sp,true);return InteractionResult.CONSUME;}b.control(sp,0,0);return InteractionResult.CONSUME;}player.displayClientMessage(net.minecraft.network.chat.Component.translatable("adc01.use_panel"),true);return InteractionResult.FAIL;}
 @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult h){return interact(s,l,p,player,InteractionHand.MAIN_HAND);}@Override protected net.minecraft.world.ItemInteractionResult useItemOn(net.minecraft.world.item.ItemStack stack,BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult h){return interact(s,l,p,player,hand).consumesAction()?net.minecraft.world.ItemInteractionResult.sidedSuccess(l.isClientSide):net.minecraft.world.ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;}
 @Override public VoxelShape getShape(BlockState s,BlockGetter getter,BlockPos p,CollisionContext c){var b=getter instanceof Level l?main(l,p,s):null;return AdcGeometry.MODEL.shape(s.getValue(FACING),s.getValue(PART),b==null?0:b.yaw,b==null?25:b.pitch);}@Override public VoxelShape getCollisionShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){if(l instanceof Level level&&c instanceof EntityCollisionContext context&&context.getEntity()instanceof AdcShell shell&&shell.from(main(level,p,s)))return Shapes.empty();return getShape(s,l,p,c);}@Override public VoxelShape getOcclusionShape(BlockState s,BlockGetter l,BlockPos p){return Shapes.empty();}@Override public int getLightBlock(BlockState s,BlockGetter l,BlockPos p){return 0;}@Override public boolean propagatesSkylightDown(BlockState s,BlockGetter l,BlockPos p){return true;}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.INVISIBLE;}
 @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return s.getValue(PART)==0?new AdcBlockEntity(p,s):null;}@Override public <T extends BlockEntity>BlockEntityTicker<T>getTicker(Level l,BlockState s,BlockEntityType<T>t){return !l.isClientSide&&s.getValue(PART)==0?createTickerHelper(t,AddonBlockEntities.ADC01.get(),AdcBlockEntity::tick):null;}
 @Override public BlockState playerWillDestroy(Level l,BlockPos p,BlockState s,Player player){if(!l.isClientSide&&player instanceof net.minecraft.server.level.ServerPlayer sp){var b=main(l,p,s);if(b!=null&&AdcEvents.mayRemove(sp,b))b.remove(sp,!sp.isCreative());}return super.playerWillDestroy(l,p,s,player);}
 @Override public void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){if(!l.isClientSide&&!MUTATING.get()&&!s.is(next.getBlock())){var b=main(l,p,s);if(b!=null)b.remove(null,!l.restoringBlockSnapshots);else if(l instanceof net.minecraft.server.level.ServerLevel sl)DefenseData.get(sl).removeAt(sl,root(p,s),3);}super.onRemove(s,l,p,next,moving);}
 @Override public void neighborChanged(BlockState s,Level l,BlockPos p,Block block,BlockPos at,boolean moving){if(l.isClientSide||MUTATING.get())return;var root=root(p,s);for(var c:AdcGeometry.MODEL.support){var ground=AdcGeometry.MODEL.cell(root,s.getValue(FACING),c).below();if(at.equals(ground)&&!l.getBlockState(ground).isFaceSturdy(l,ground,Direction.UP)){var b=main(l,p,s);if(b!=null)b.remove(null,true);break;}}}@Override public BlockState rotate(BlockState s,Rotation r){return s.setValue(FACING,r.rotate(s.getValue(FACING)));}@Override public BlockState mirror(BlockState s,Mirror m){return rotate(s,m.getRotation(s.getValue(FACING)));}
}
